import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.B-XtCDNB.js";const i="/assets/vala-gdbus-server-module.WWX3MnHg.png",g=JSON.parse('{"title":"3.6. C Code Generation","description":"3.6. C Code Generation In the previous Vala compiler steps, we verified that the validity of the Vala code. Now the compiler is ready to generate C code from the Vala source code. In the...","frontmatter":{"prev":{"text":"3.5. Flow Analyzer","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-05-flow-analyzer"},"next":{"text":"3.7. C Code Compilation and Linking","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-07-c-code-compilation-and-linking"}},"headers":[],"relativePath":"guides/compiler-guide/03-00-the-vala-compiler/03-06-c-code-generation.md","filePath":"guides/compiler-guide/03-00-the-vala-compiler/03-06-c-code-generation.md","lastUpdated":1785986502000}'),n={name:"guides/compiler-guide/03-00-the-vala-compiler/03-06-c-code-generation.md"};function d(c,e,s,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-6-c-code-generation" tabindex="-1">3.6. C Code Generation <a class="header-anchor" href="#_3-6-c-code-generation" aria-label="Permalink to &quot;3.6. C Code Generation&quot;">​</a></h1><p>In the previous Vala compiler steps, we verified that the validity of the Vala code. Now the compiler is ready to generate C code from the Vala source code.</p><p>In the <code>Vala.Compiler.run ()</code> method, the compiler will eventually call <code>Vala.CodeContext.codegen.emit ()</code> which starts the C code generation process.</p><h2 id="_3-6-1-how-the-code-generation-works" tabindex="-1">3.6.1 How The Code Generation Works <a class="header-anchor" href="#_3-6-1-how-the-code-generation-works" aria-label="Permalink to &quot;3.6.1 How The Code Generation Works&quot;">​</a></h2><h3 id="_3-6-1-1-deciding-which-vala-codegenerator-instance-type-to-use" tabindex="-1">3.6.1.1 Deciding which Vala.CodeGenerator instance type to use <a class="header-anchor" href="#_3-6-1-1-deciding-which-vala-codegenerator-instance-type-to-use" aria-label="Permalink to &quot;3.6.1.1 Deciding which Vala.CodeGenerator instance type to use&quot;">​</a></h3><p>Vala.CodeContext.codegen is a property for an instance of <code>Vala.CodeGenerator</code>. The object type is different based on the compiler profile that the user set:</p><ul><li>GObject profile: <code>GDBusServerModule</code>.</li><li>Otherwise: <code>CCodeDelegateModule</code></li></ul><h3 id="_3-6-1-2-modules-pattern-with-c-code-generator" tabindex="-1">3.6.1.2 Modules Pattern with C Code Generator <a class="header-anchor" href="#_3-6-1-2-modules-pattern-with-c-code-generator" aria-label="Permalink to &quot;3.6.1.2 Modules Pattern with C Code Generator&quot;">​</a></h3><p><code>Vala.CodeGenerator</code> is an abstract class that is a code visitor for generating code. This is the base class for code generators in the compiler, it contains abstract methods to be overriden by subclasses that help wit hthe code generation process too.</p><p>The actual code generation logic is contained in its subclasses. The direct subclass of <code>Vala.CodeGenerator</code> is <code>Vala.CCodeBaseModule</code>. Which actually overrides the <code>Vala.CodeVisitor</code> methods.</p><p><code>Vala.CCodeBaseModule</code> contains the logic that provides the base functionality for generating C code from Vala code.</p><p>Inheritance is used to stack code generation functionality between subclasses, expanding on the method overrides of parent classes. are modules that provide functionality for the code generation process.</p><p><code>Vala.CCodeBaseModule</code> is a module that provides base functionality for the code generation process. For additional functionality, <code>Vala.CCodeStructModule</code> extends the <code>Vala.CCodeBaseModule</code> class, however the module specifically handles how C structs should be generated from Vala code. We keep stacking functionality using modules in the inheritance tree until we&#39;ve reached the desired amount of functionality. That&#39;s where the instance types based on the profiles come in. They&#39;ve implemented an appropriate amount of functionality to be able to generate code for those profiles.</p><p>However, as more features are added to the language, the inhertiance trees for the code generation classes <code>Vala.CodeGenerator</code> classes may grow further. Or a slightly different inheritance tree may be created for new profile, with modules that are specific for that new profile.</p><p>Here&#39;s the object hiearchy graph for the <code>Vala.GDBusServerModule</code> class:</p><p><img src="'+i+'" alt="Vala.GDBusServerModule Object Hierarchy Graph"></p>',16)])])}const m=o(n,[["render",d]]);export{g as __pageData,m as default};
